alter proc [dbo].[GetPageInformation]
@o varchar(50), @oid int, @rid int as begin declare @breadcrumbsRaw table ([Level] int, [TypeName] nvarchar(500), [Name] nvarchar(max), [TypeUrl] nvarchar(2500), [Url] nvarchar(2500)); declare @breadcrumbs table ([Name] nvarchar(max), [Url] nvarchar(2500), Active bit, IsType bit);
with h as ( select A.ID, A.[ObjectID], A.AssetTypeID, I.SubjectID as [ParentID], 0 as [Level] from Asset A left join PredicateIntersect I on I.Object = A.Object and I.ObjectID = A.ObjectID and I.PredicateType = 3 where A.[Object] = @o and A.ObjectID = @oid union all select P.ID, P.[ObjectID] as ID, P.AssetTypeID, I.SubjectID as ParentID, h.[Level]-1 as [Level] from Asset P inner join h on P.[Object] = @o and P.ObjectID = h.ParentID outer apply ( select SubjectID from PredicateIntersect where Object = P.Object and ObjectID = P.ObjectID and PredicateType = 3 ) I )
insert into @breadcrumbsRaw select distinct [Level], ltrim(rtrim(T.Name)), ltrim(rtrim(D.DisplayValue)), UT.Url, U.Url from h inner join AssetType T on T.ID = h.AssetTypeID left join dbo.GetAssetDisplayValue() D on D.ID = h.ID cross apply dbo.GetAssetUrlByID(h.ID) U cross apply dbo.GetAssetTypeUrlById(T.ID) UT where ltrim(rtrim(T.Name)) is not null and ltrim(rtrim(D.DisplayValue)) is not null order by [Level]
select distinct O.[Uid], O.ObjectID as ID, O.ID as AssetID, O.AssetTypeID, OD.DisplayValue, T.Name as [TypeName], case when Dash.[Count] > 0 then cast(1 as bit) else cast(0 as bit) end as HasDashboards, case when Work.[Count] > 0 then cast(1 as bit) else cast(0 as bit) end as HasWorkflow, case when Child.[Count] > 0 then cast(1 as bit) else cast(0 as bit) end as HasChildArtifacts, case when Attr.[Count] > 0 then cast(1 as bit) else cast(0 as bit) end as AllowAttributes, case when Hier.[Count] > 0 then cast(1 as bit) else cast(0 as bit) end as AllowPredicateHierarchies, ( select * from ( select P.ID as [ID], P.Name as [Name] from [Predicate] P where exists(SELECT * FROM IntersectType IT WHERE P.[type] = 6 and P.ID = IT.PredicateID and ((IT.Subject = T.Object and IT.SubjectID = T.ObjectID) OR (IT.Object = T.Object and IT.ObjectID =T.ObjectID))) union select P.ID as [ID], P.Name as [Name] from [NymRelation] R inner join [dbo].[predicate] P on P.ID = R.PredicateID where R.[Object] = T.Object and R.ObjectID = T.ObjectID ) NMT for json path ) as NymTypes, ( select * from @breadcrumbsRaw for json path ) as Breadcrumbs from Asset O inner join AssetType T on T.ID = O.AssetTypeID left join dbo.GetAssetDisplayValue() OD on OD.ID = O.ID
cross apply ( select count(1) as [Count] from Report where ObjectType = O.Object and ObjectID = T.ObjectID ) Dash cross apply ( select count(1) as [Count] from workflow.EventRegistration WER inner join workflow.Type WT on WER.TypeID = WT.ID and WT.PublishedVersionID is not null and WT.[State] = 1 and WER.ChangeType = 8 where WER.Object = T.Object and WER.ObjectID = T.ObjectID ) Work cross apply ( select count(1) as [Count] from [PredicateIntersect] where Subject = O.Object and SubjectID = O.ObjectID and PredicateType = 3 ) Child cross apply ( select count(1) as [Count] from AttributeTypeRelation where ObjectType = T.Object and ObjectID = T.ObjectID ) Attr cross apply ( select count(1) as [Count] from IntersectType IT inner join [Predicate] P on P.ID = IT.PredicateID and P.[Type] = 3 where ((IT.Subject = T.Object and IT.SubjectID = T.ObjectID) OR (IT.Object = T.Object and IT.ObjectID = T.ObjectID)) ) Hier where O.Object = @o and O.ObjectID = @oid and not exists (select 1 from ResponsibilityDetail where PermissionsBitMask & 1 = 0 and ResourceID = @rid and ( (AssetID = O.ID) OR (AssetTypeID = O.AssetTypeID and AssetID = 0))) for json path, WITHOUT_ARRAY_WRAPPER end
